{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf7f2;--card:#fff7ec;--muted:#6b6b6b;--accent:#8a5a2b;--accent-2:#c08a55;--glass:rgba(255,255,255,0.6);font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial}
    html,body{height:100%}
    body{margin:0;background:linear-gradient(180deg, var(--bg), #f7efe6);color:#2b2b2b;-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:1.1rem 1.2rem;background:transparent}
    .brand{display:flex;gap:.9rem;align-items:center}
    .logo{width:48px;height:48px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:grid;place-items:center;color:#fff;font-weight:700}
    nav a{margin-left:1rem;color:var(--muted);text-decoration:none;font-size:.95rem}
    main{max-width:920px;margin:2rem auto;padding:1.2rem}
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.7),transparent);padding:1.6rem;border-radius:12px;display:grid;gap:1rem}
    .kicker{font-size:.85rem;color:var(--accent);font-weight:600}
    h1{margin:.15rem 0;font-size:1.6rem}
    p.lead{margin:0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:1rem;margin-top:1rem}
    .cards{display:grid;gap:1rem}
    .tier{background:var(--card);padding:1rem;border-radius:10px;box-shadow:0 6px 18px rgba(45,25,10,0.06)}
    .tier h3{margin:.1rem 0}
    .price{font-size:1.6rem;color:var(--accent);font-weight:700}
    .muted{color:var(--muted);font-size:.95rem}
    .cta{display:inline-block;margin-top:.6rem;padding:.6rem .9rem;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none}
    .small{font-size:.86rem}
    footer.cta-area{margin-top:1.2rem;padding:1rem;border-radius:10px;background:linear-gradient(180deg,rgba(138,90,43,0.06),transparent)}
    /* Session Planner */
    .planner{background:#fff;padding:1rem;border-radius:10px;box-shadow:0 8px 30px rgba(40,20,8,0.06)}
    .field{display:flex;flex-direction:column;margin-bottom:.65rem}
    label{font-size:.86rem;margin-bottom:.25rem;color:#3a3a3a}
    input[type=text],select,textarea{padding:.5rem;border:1px solid #ebdfd1;border-radius:8px}
    .row{display:flex;gap:.6rem}
    .row .field{flex:1}
    button{cursor:pointer}
    .btn-ghost{background:transparent;border:1px solid var(--accent);color:var(--accent);padding:.45rem .7rem;border-radius:8px}
    .btn-primary{background:var(--accent);color:#fff;border:none;padding:.55rem .8rem;border-radius:8px}
    .summary{white-space:pre-wrap;background:#faf7f4;padding:.85rem;border-radius:8px;border:1px dashed #e9dccf;margin-top:.6rem;font-size:.95rem}
    .faq{margin-top:1rem}
    .faq h4{margin:.5rem 0}
    /* reveal */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .6s ease,transform .6s ease}
    .reveal-visible{opacity:1;transform:none}
    @media(prefers-reduced-motion:reduce){.reveal{transition:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:.85rem;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Primary Navigation">
      <a href="index.html">Nest</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Formulations</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html" style="font-weight:700;color:var(--accent)">Rates</a>
      <a href="about.html">About</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" data-reveal>
      <div class="kicker">Rates & alignment</div>
      <h1>Practical scent programs for day-to-day balance</h1>
      <p class="lead">Carefully structured session options and a rolling support program. Sessions and blends are designed with safety and gentle practicality — suggestions that may support rest, focus, or a sense of ease.</p>
    </section>

    <div class="grid">
      <div class="cards">
        <section class="tier reveal" data-reveal>
          <h3>Intro Support</h3>
          <div class="price">$95</div>
          <div class="muted">Single 60-min consult + take-home mini blend</div>
          <p class="small">A gentle first meeting to clarify goals and create a simple, safe blend for home use. Includes dilution guidance and patch-test instructions.</p>
          <a class="cta" href="book.html">Book an Intro</a>
        </section>

        <section class="tier reveal" data-reveal>
          <h3>Scent Series</h3>
          <div class="price">3 sessions • $260</div>
          <div class="muted">Three guided sessions over 6–8 weeks</div>
          <p class="small">A focused series that builds a personal toolkit of scented practices and formulations you can use between sessions. Includes written protocol.</p>
          <a class="cta" href="book.html">Reserve Series</a>
        </section>

        <section class="tier reveal" data-reveal>
          <h3>Scent Circle</h3>
          <div class="price">$32/month</div>
          <div class="muted">Ongoing support — monthly curated blends & check-ins</div>
          <p class="small">A subscription for steady access to seasonal blends, short check-ins, and members-only notes. Cancel any time. New members receive a starter blend.</p>
          <a class="cta" href="book.html">Join the Circle</a>
        </section>

        <footer class="cta-area reveal" data-reveal>
          <strong>Need help choosing?</strong>
          <p class="small">Use the Session Planner to build a simple, personalised plan and get a downloadable summary you can bring to your booking.</p>
          <a class="btn-ghost" href="#planner">Open Planner</a>
        </footer>
      </div>

      <aside class="planner reveal" id="planner" data-reveal>
        <h3>Session Planner</h3>
        <p class="small muted">Answer a few questions and we'll suggest session pacing and a safe topical dilution. This is a supportive planning tool and not medical advice.</p>
        <div>
          <div class="field">
            <label for="name">Your name</label>
            <input id="name" type="text" placeholder="First name">
          </div>
          <div class="field">
            <label for="goal">Primary aim</label>
            <select id="goal">
              <option value="calm">Calm / stress ease</option>
              <option value="focus">Focus / clarity</option>
              <option value="sleep">Sleep support</option>
              <option value="uplift">Uplift / mood</option>
            </select>
          </div>
          <div class="field">
            <label>Aroma preferences (pick 1–2)</label>
            <div style="display:flex;gap:.4rem;flex-wrap:wrap">
              <label><input type="checkbox" value="lavender"> Lavender</label>
              <label><input type="checkbox" value="bergamot"> Bergamot</label>
              <label><input type="checkbox" value="frankincense"> Frankincense</label>
              <label><input type="checkbox" value="peppermint"> Peppermint</label>
              <label><input type="checkbox" value="sweetorange"> Sweet Orange</label>
            </div>
          </div>
          <div class="field">
            <label for="frequency">Session rhythm</label>
            <select id="frequency">
              <option value="single">One session</option>
              <option value="series">Series (3 sessions)</option>
              <option value="monthly">Ongoing (monthly)</option>
            </select>
          </div>

          <div class="row">
            <div class="field">
              <label><input type="checkbox" id="pregnancy"> Pregnancy or breastfeeding</label>
            </div>
            <div class="field">
              <label><input type="checkbox" id="pets"> Pets at home</label>
            </div>
          </div>

          <div style="display:flex;gap:.4rem;margin-top:.6rem">
            <button class="btn-primary" id="build">Build plan</button>
            <button class="btn-ghost" id="reset">Reset</button>
          </div>

          <div id="resultWrap" style="display:none">
            <h4 style="margin:.6rem 0">Your plan</h4>
            <div class="summary" id="summary"> </div>
            <div style="display:flex;gap:.5rem;margin-top:.6rem">
              <button class="btn-primary" id="copy">Copy summary</button>
              <a id="bookNow" class="btn-ghost" href="book.html">Use plan to book</a>
              <a id="download" class="btn-ghost" href="#">Download .txt</a>
            </div>
          </div>
        </div>
      </aside>
    </div>

    <section class="faq reveal" data-reveal>
      <h3>Common questions</h3>
      <div>
        <h4>Are your blends safe?</h4>
        <p class="muted small">Blends are prepared with safety-forward dilution guidance. Topical suggestions will include a conservative dilution (often 1–3%) and a patch test is recommended before regular use.</p>

        <h4>What about pets and pregnancy?</h4>
        <p class="muted small">We adapt suggestions when pets live in the home and avoid certain oils during pregnancy or breastfeeding. Please disclose these in your booking so we plan safely.</p>

        <h4>Do you make claims?</h4>
        <p class="muted small">We do not make medical claims. Our practices and blends may support relaxation, focus, or a sense of ease; they are not treatments.</p>
      </div>
    </section>

  </main>

  <script>
    // Scroll reveal with prefers-reduced-motion support
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('[data-reveal]');
      if(prefersReduce){
        reveals.forEach(el=>el.classList.add('reveal-visible'));
        return;
      }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(entry=>{
          if(entry.isIntersecting){
            entry.target.classList.add('reveal-visible');
            io.unobserve(entry.target);
          }
        });
      },{threshold:0.12});
      reveals.forEach(el=>io.observe(el));
    })();

    // Session Planner logic
    (function(){
      const build = document.getElementById('build');
      const reset = document.getElementById('reset');
      const summaryEl = document.getElementById('summary');
      const wrap = document.getElementById('resultWrap');
      const copy = document.getElementById('copy');
      const download = document.getElementById('download');
      const bookNow = document.getElementById('bookNow');

      function getCheckedAromas(){
        return Array.from(document.querySelectorAll('#planner input[type=checkbox]'))
          .filter(i=>i.checked && i.id!=='pregnancy' && i.id!=='pets')
          .map(i=>i.value);
      }

      function generatePlan(){
        const name = (document.getElementById('name').value || 'Client').trim();
        const goal = document.getElementById('goal').value;
        const freq = document.getElementById('frequency').value;
        const pregnancy = document.getElementById('pregnancy').checked;
        const pets = document.getElementById('pets').checked;
        const aromas = getCheckedAromas();

        const goalMap = {calm:'calm/grounding',focus:'focus/clarity',sleep:'sleep support',uplift:'mood lift'};
        const frequencyMap = {single:'Single session',series:'Three-session series',monthly:'Monthly support'};
        const dilution = pregnancy? 'Use only inhalation and consult for pregnancy-safe options; topical use generally avoided unless cleared.' : 'Suggested topical dilution: ~2% (approx. 12 drops per 30ml carrier) — perform a patch test before regular use.';

        let aromasText = aromas.length? aromas.join(', '): 'No specific aroma preference noted.';
        if(pets) aromasText += ' — avoid essential oils known to be risky for your pet; plan will prioritize safer inhalation approaches.';

        const sessionSuggestion = frequencyMap[freq];
        const notes = [];
        notes.push('Patch test: place 1 drop of diluted blend on inner forearm and wait 24 hours for any reaction.');
        if(pregnancy) notes.push('Pregnancy note: many oils are avoided during pregnancy; this plan will prioritize non-topical or pregnancy-appropriate options and defer topical suggestions until consultation.');
        if(pets) notes.push('Pet caution: use inhalation in well-ventilated spaces, keep blends out of reach, and avoid oils toxic to cats and certain dog breeds.');

        const planText = [
          `Name: ${name}`,
          `Primary aim: ${goalMap[goal] || goal}`,
          `Program suggestion: ${sessionSuggestion}`,
          `Aroma preferences: ${aromasText}`,
          '',
          'Suggested simple topical blend (example):',
          pregnancy? '  • Topical avoided until cleared; use inhalation or diffuser instead.' : '  • Carrier: 30 ml (1 oz) sweet almond or fractionated coconut oil',
          pregnancy? '' : '  • Essential oils: Lavender 6 drops + Sweet Orange 6 drops (total 12 drops = ~2% dilution)',
          '',
          `Safety & notes:`,
          ...notes.map(n=>'  • '+n),
          '',
          'Next step: Bring this summary to your session booking. We will personalise blends and application based on a fuller intake.'
        ].join('\n');

        return planText;
      }

      build.addEventListener('click',()=>{
        const text = generatePlan();
        summaryEl.textContent = text;
        wrap.style.display = 'block';
        // prepare download
        const blob = new Blob([text],{type:'text/plain'});
        const url = URL.createObjectURL(blob);
        download.href = url;
        download.download = 'session-plan.txt';
        bookNow.href = 'book.html';
      });

      reset.addEventListener('click',()=>{
        document.getElementById('name').value='';
        document.getElementById('goal').selectedIndex=0;
        document.getElementById('frequency').selectedIndex=0;
        document.getElementById('pregnancy').checked=false;
        document.getElementById('pets').checked=false;
        document.querySelectorAll('#planner input[type=checkbox]').forEach(cb=>cb.checked=false);
        wrap.style.display='none';
      });

      copy.addEventListener('click',async ()=>{
        const txt = summaryEl.textContent || '';
        try{
          await navigator.clipboard.writeText(txt);
          copy.textContent = 'Copied!';
          setTimeout(()=>copy.textContent='Copy summary',1200);
        }catch(e){
          copy.textContent = 'Copy failed';
        }
      });

    })();
  </script>
</body>
</html>"} 
